import {Client} from '@modelcontextprotocol/sdk/client/index.js';
import {StreamableHTTPClientTransport} from '@modelcontextprotocol/sdk/client/streamableHttp.js';
import fs from 'fs';
const D='<scratch>';
const tk=JSON.parse(fs.readFileSync(D+'maria-token.json','utf8'));
const token=tk.token||tk.key||Object.values(tk).find(v=>typeof v==='string'&&v.startsWith('done_'));
const c=new Client({name:'maria-agent',version:'1'});
await c.connect(new StreamableHTTPClientTransport(new URL('http://localhost:8810/mcp'),{requestInit:{headers:{Authorization:'Bearer '+token}}}));
const [,,tool,arg]=process.argv;
if(tool==='list'){console.log((await c.listTools()).tools.map(t=>t.name).join(','));}
else{const r=await c.callTool({name:tool,arguments:arg?JSON.parse(arg):{}});console.log(r.content.map(x=>x.text||'[img]').join('\n'));}
await c.close();
EOF
